class Queue:
    def __init__(self) -> None:
        self._jobs = []
        self._sequence = 0

    def push(self, name: str, urgent: bool = False) -> None:
        self._jobs.append((0 if urgent else 1, self._sequence, name))
        self._sequence += 1

    def pop(self) -> str:
        self._jobs.sort()
        return self._jobs.pop(0)[2]

