class Queue:
    def __init__(self) -> None:
        self._urgent = []
        self._ordinary = []

    def push(self, name: str, urgent: bool = False) -> None:
        (self._urgent if urgent else self._ordinary).append(name)

    def pop(self) -> str:
        if self._urgent:
            return self._urgent.pop(0)
        return self._ordinary.pop(0)

